// Oeste BlockFaq — Topanga block (v0.4.8).
// A full page section composed from Oeste components, inlined below so
// this file is self-contained. Copy-paste ready. Requires: React 18+,
// Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/blocks.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/blocks/faq
import React from "react";

const FOCUS = "focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#1c1917] dark:focus-visible:outline-[#f5f3ef]";

const TOUCH = "min-h-11";

const BUTTON_VARIANTS = {
  primary: "bg-[#c47d3b] text-[#1c1917] hover:opacity-90 dark:bg-[#db914e] dark:text-[#1c1917]",
  secondary: "border border-[#1c1917]/20 bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  ghost: "bg-transparent text-[#1c1917] hover:bg-[#1c1917]/5 dark:text-[#f5f3ef] dark:hover:bg-[#f5f3ef]/5",
  danger: "bg-[#a83e22] text-[#f6f4f1] hover:opacity-90 dark:bg-[#e07a52] dark:text-[#121110]",
};

const BUTTON_SIZES = {
  sm: "px-3 py-2 text-sm",
  md: "px-5 py-3 text-base",
  lg: "px-6 py-3.5 text-lg",
};

export function Accordion({ items, allowMultiple = false }) {
  const id = React.useId();
  const [open, setOpen] = React.useState([]);
  const toggle = (i) => setOpen((prev) => prev.includes(i) ? prev.filter((x) => x !== i) : (allowMultiple ? [...prev, i] : [i]));
  return (
    <div className="divide-y divide-[#1c1917]/10 dark:divide-[#f5f3ef]/10">
      {items.map((item, i) => {
        const isOpen = open.includes(i);
        return (
          <div key={i}>
            <h3 className="m-0">
              <button type="button" aria-expanded={isOpen} aria-controls={`${id}-panel-${i}`} id={`${id}-trigger-${i}`} onClick={() => toggle(i)}
                className={`${TOUCH} flex w-full items-center justify-between gap-3 py-3 text-left font-medium text-[#1c1917] dark:text-[#f5f3ef] ${FOCUS}`}>
                {item.title}<span aria-hidden="true">{isOpen ? "−" : "+"}</span>
              </button>
            </h3>
            <div id={`${id}-panel-${i}`} role="region" aria-labelledby={`${id}-trigger-${i}`} hidden={!isOpen} className="pb-4 text-[#1c1917] dark:text-[#f5f3ef]">{item.content}</div>
          </div>
        );
      })}
    </div>
  );
}

export function Button({ children, variant = "primary", size = "md", disabled = false, loading = false, type = "button", onClick, icon = null }) {
  return (
    <button
      type={type}
      disabled={disabled || loading}
      onClick={onClick}
      aria-busy={loading || undefined}
      className={`${TOUCH} inline-flex items-center justify-center gap-2 rounded-md font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${BUTTON_VARIANTS[variant]} ${BUTTON_SIZES[size]} ${FOCUS}`}
    >
      {loading ? <span aria-hidden="true">…</span> : icon}
      {children}
    </button>
  );
}

export function Collapsible({ title, children, open: openProp, onOpenChange }) {
  const [inner, setInner] = React.useState(false);
  const open = openProp !== undefined ? openProp : inner;
  const id = React.useId();
  const toggle = () => { const next = !open; if (onOpenChange) onOpenChange(next); else setInner(next); };
  return (
    <div>
      <button type="button" aria-expanded={open} aria-controls={`${id}-panel`} onClick={toggle}
        className={`${TOUCH} flex w-full items-center justify-between gap-3 rounded-md border border-[#1c1917]/20 px-4 text-left font-semibold text-[#1c1917] dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef] ${FOCUS}`}>
        {title}<span aria-hidden="true">{open ? "−" : "+"}</span>
      </button>
      <div id={`${id}-panel`} hidden={!open} className="pt-3 text-[#1c1917] dark:text-[#f5f3ef]">{children}</div>
    </div>
  );
}

export function Separator({ orientation = "horizontal", decorative = true }) {
  if (orientation === "vertical") {
    return decorative
      ? <span aria-hidden="true" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />
      : <span role="separator" aria-orientation="vertical" className="inline-block w-px self-stretch bg-[#1c1917]/10 dark:bg-[#f5f3ef]/10" />;
  }
  return decorative
    ? <hr aria-hidden="true" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />
    : <hr role="separator" aria-orientation="horizontal" className="my-4 border-0 border-t border-[#1c1917]/10 dark:border-[#f5f3ef]/10" />;
}

export function BlockFaq({ variant = "standard" }) {
  const items = [
    { title: "How much does Fieldbook cost?", content: "Plans run per person, per month: Starter is $12 monthly or $9 on annual billing, Studio is $24 or $18, and Practice is $48 or $36. Every plan includes every feature; plans differ by scale, not by unlocks." },
    { title: "Is there a free trial?", content: "Yes. Every plan starts with 30 days free, and no card is asked for up front. If you do nothing at the end of the trial, the workspace simply pauses; your pages stay readable for another 60 days." },
    { title: "Can clients read our project pages?", content: "Yes, on Studio and Practice plans. A client sees the page you share: notes, decisions, dates, and files, without needing an account or a login. You choose which pages are shared, and sharing can be withdrawn at any time." },
    { title: "How do we move existing projects in?", content: "Most studios start with their active projects and leave the archive where it is. Notes paste in as text, files attach to the page, and a typical project page takes about nine minutes to set up. Imports from common note tools are supported on every plan." },
    { title: "What happens to our pages if we cancel?", content: "Your pages export as plain files you keep, in full, including decisions and attachments. Cancellation takes effect at the end of the billing period, and annual plans are refunded pro rata for unused months." },
    { title: "Who can see a project page inside our studio?", content: "Only the people you add to the workspace. A page is visible to its project members and to workspace owners; there is no public directory of pages, and nothing is indexed or shared outside your studio." },
  ];
  if (variant === "compact") {
    return (
      <div className="bg-[#f6f4f1] px-6 py-8 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef]">
        <div className="space-y-4">
          {items.slice(0, 4).map((it) => (
            <Collapsible key={it.title} title={it.title}>
              <p className="leading-relaxed text-[#706963] dark:text-[#9e968f]">{it.content}</p>
            </Collapsible>
          ))}
        </div>
      </div>
    );
  }
  return (
    <section className="bg-[#f6f4f1] px-6 py-16 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef] lg:px-8 lg:py-24">
      <div className="mx-auto max-w-[1200px]">
        <div className="max-w-[640px]">
          <h2 className="text-[1.75rem] font-semibold leading-tight tracking-[-0.025em] lg:text-[2.5rem]">Questions, answered plainly</h2>
          <p className="mt-4 leading-relaxed text-[#706963] dark:text-[#9e968f]">The six questions every studio asks before switching, with the short answer first.</p>
        </div>
        <div className="mt-10 max-w-[880px]">
          <Accordion items={items} />
        </div>
        <div className="mt-10 max-w-[880px]">
          <Separator />
          <div className="mt-6 flex flex-wrap items-center gap-4">
            <p className="leading-relaxed text-[#706963] dark:text-[#9e968f]">Still deciding? Talk it through with a person.</p>
            <Button variant="secondary" onClick={() => {}}>Contact support</Button>
          </div>
        </div>
      </div>
    </section>
  );
}
